mockup.css:
.mock-hero-index-hero { background: #fbfaf6; color: #16150f; font-family: "Iowan Old Style", Palatino, Georgia, serif;
  padding: 7cqw 5cqw 4cqw; display: flex; flex-direction: column; gap: 3cqw; }
.mock-hero-index-hero h4 { margin: 0; font-size: 6.4cqw; line-height: 1; letter-spacing: -.02em; max-width: 60%; }
.mock-hero-index-hero ol { margin: 0; padding: 0; list-style: none; display: grid; }
.mock-hero-index-hero li { display: grid; grid-template-columns: 4cqw 1fr auto; gap: 2.4cqw; align-items: baseline;
  border-top: 1px solid rgba(22,21,15,.16); padding: 1.5cqw 0;
  font-family: "Inter", ui-sans-serif, sans-serif; font-size: 2cqw; }
.mock-hero-index-hero li b { font-family: ui-monospace, monospace; font-weight: 500; font-size: 1.5cqw;
  color: #a8340f; }
.mock-hero-index-hero li em { font-style: normal; opacity: .45; font-size: 1.6cqw; }
